from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        max_p = max(points)

        def feasible(T: int) -> bool:
            if T <= 0:
                return True
            total = 0
            extra = 0  # carry-over visits to position i from oscillation at i-1
            for i in range(n):
                c_i = (T + points[i] - 1) // points[i]
                if i == n - 1:
                    # Last position: may skip advancing if extra already suffices
                    if extra >= c_i:
                        pass
                    else:
                        total += 1  # advance into position i
                        if 1 + extra < c_i:
                            need = c_i - 1 - extra
                            total += 2 * need
                            # oscillate to i-1 since i+1 doesn't exist; same move count
                else:
                    total += 1  # advance into position i
                    if 1 + extra < c_i:
                        need = c_i - 1 - extra
                        total += 2 * need
                        extra = need  # carry to position i+1
                    else:
                        extra = 0
                if total > m:
                    return False
            return total <= m

        lo, hi = 0, max_p * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

